# Components of 8-background in demo2 under 4/8 connectivity, inspect not edge-connected
n=16
lines={(0,8),(1,9),(2,10),(3,11),(4,0),(4,12),(5,1),(5,13),(6,2),(6,6),(6,14),(7,3),(7,7),(7,15),(8,4),(8,8),(9,5),(9,9),(10,10),(11,2),(11,11),(12,3),(12,12),(13,4),(13,13),(14,5),(14,14),(15,6)}
for diag in [False,True]:
 dxy=[(-1,0),(1,0),(0,-1),(0,1)]
 if diag:dxy += [(-1,-1),(-1,1),(1,-1),(1,1)]
 seen=set(); comps=[]
 for r in range(n):
  for c in range(n):
   if (r,c) in lines or (r,c) in seen:continue
   stack=[(r,c)];seen.add((r,c));comp=set(); edge=False
   while stack:
    p=stack.pop();comp.add(p);y,x=p
    if y in [0,n-1] or x in [0,n-1]:edge=True
    for dy,dx in dxy:
     q=(y+dy,x+dx)
     if 0<=q[0]<n and 0<=q[1]<n and q not in lines and q not in seen:
      seen.add(q);stack.append(q)
   comps.append((edge,comp))
 enclosed=[(len(comp), sorted(comp)[:3]) for edge,comp in comps if not edge]
 print('diag',diag,'enclosed',enclosed)

def components_from_pts(pts):
    # segment by u, contiguous row runs
    by={}
    for r,c in pts: by.setdefault(c-r,[]).append(r)
    segs=[]
    for u,rs in by.items():
      rs=sorted(rs); st=pr=rs[0]
      for r in rs[1:]:
       if r==pr+1: pr=r
       else: segs.append((u,st,pr)); st=pr=r
      segs.append((u,st,pr))
    return segs

def fill_pairseg(pts,n=16):
    segs=components_from_pts(pts)
    fill=set()
    for i,(u1,r1a,r1b) in enumerate(segs):
      for u2,r2a,r2b in segs[i+1:]:
       vlo=max(2*r1a+u1,2*r2a+u2); vhi=min(2*r1b+u1,2*r2b+u2)
       if vlo>vhi: continue
       for r in range(n):
        for c in range(n):
         u=c-r; v=r+c
         if min(u1,u2)<u<max(u1,u2) and vlo<=v<=vhi and (r,c) not in pts: fill.add((r,c))
    return segs,fill
